export fn permutation_cipher(v:[*c]const i64,n:usize)i64{if(v==null or n<2 or n>74 or v[0]<0 or v[0]>64)return -1;const len:usize=@intCast(v[0]);if(n<len+2)return -1;const kp=len+1;if(v[kp]<1 or v[kp]>8)return -1;const k:usize=@intCast(v[kp]);if(n!=kp+k+1)return -1;var seen=[_]bool{false}**8;for(0..k)|i|{const x=v[kp+1+i];if(x<1 or x>@as(i64,@intCast(k)) or seen[@intCast(x-1)])return -1;seen[@intCast(x-1)]=true;}var t=[_]u8{0}**128;var m:usize=0;for(0..len)|i|{const x=v[i+1];if(x<0 or x>127)return -1;var c:u8=@intCast(x);if(c==32 or (c>=9 and c<=13))continue;if(c>=97 and c<=122)c-=32;t[m]=c;m+=1;}while(m%k!=0){t[m]='X';m+=1;}var h:u64=0;var b:usize=0;while(b<m):(b+=k){for(0..k)|j|{const idx:usize=@intCast(v[kp+1+j]-1);h=(h*257+t[b+idx])%1000000007;}}return @intCast(h);}
